import React from 'react';

import { useNavigate } from 'react-router-dom';

import PageLoader from '@components/PageLoader';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';

import { getHikingListForUserOrFriend } from '../../Hiking/@services/hikingWithFriend.service';
import { IHikingWithFriend } from '../../Hiking/@types/hikingWithFriend.types';

interface IHikingListTogetherProps {
  id_user: number;
}

const HikingListTogether: React.FC<IHikingListTogetherProps> = ({ id_user }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingWithFriend[]>([]);
  const navigate = useNavigate();
  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dt = await getHikingListForUserOrFriend({ friend: id_user });
        setData(dt);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_user]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  if (data.length === 0)
    return (
      <PohAlert variant={AlertVariant.Info}>
        Похоже тут нет походов. Все впереди! Мы узнавали :)
      </PohAlert>
    );

  return (
    <PohList
      data={data.map((h) => {
        return {
          key: h.id,
          onClick: () => navigate(`/hiking/${h.id}`),
          action: true,
          children: (
            <div className="w-100">
              <div className="d-flex w-100">
                <PohAva width={48} alt={h.name} src={h.ava} colorize className="me-2" />
                <div className="flex-grow-1">
                  <div>
                    <small className="text-muted float-end">
                      {h.type.name}: {formatDistance(h.distance)}
                    </small>
                    {h.name}
                  </div>

                  <small className="d-block text-muted">{h.description}</small>
                  <small className="d-block text-info">
                    {dateRangeToLocaleString(h.start, h.finish)}
                  </small>
                </div>
              </div>
            </div>
          ),
        };
      })}
    />
  );
};

export default HikingListTogether;
